static int guc_capture_log_remove_dw ( struct intel_guc * guc , struct __guc_capture_bufstate * buf , u32 * dw ) { struct drm_i915_private * i915 = guc_to_gt ( guc ) -> i915 ; int tries = 2 ; int avail = 0 ; u32 * src_data ; while ( tries -- ) { avail = guc_capture_buf_cnt_to_end ( buf ) ; if ( avail >= sizeof ( u32 ) ) { src_data = ( u32 * ) ( buf -> data + buf -> rd ) ; * dw = * src_data ; buf -> rd += 4 ; return 4 ; } if ( avail ) { drm_dbg ( & i915 -> drm , "GuC-Cap-Logs not dword aligned, skipping.\n" ) ; } buf -> rd = 0 ; } return 0 ; } 